window.VO = [{"id":"n01","text":"You're the only one who saw the thief's face,","at":0.24,"t0":0.12,"t1":2.16},{"id":"n02","text":"for about one second.","at":5.2,"t0":2.6,"t1":3.87},{"id":"a01","text":"Quick, before he fades.","at":8.54,"t0":4.27,"t1":6.11},{"id":"a02","text":"Round face, or long?","at":12.72,"t0":6.36,"t1":8.27},{"id":"n03","text":"You don't know, so you guess.","at":17.04,"t0":8.52,"t1":9.95},{"id":"a03b","text":"Round, then.","at":20.4,"t0":10.2,"t1":11.32},{"id":"a04","text":"And the mole. Which cheek?","at":28.36,"t0":14.18,"t1":16.03},{"id":"a05","text":"This one.","at":33,"t0":16.5,"t1":17.4},{"id":"a06","text":"That's him?","at":39.68,"t0":19.84,"t1":20.79},{"id":"n05","text":"Now pick him.","at":43.48,"t0":21.74,"t1":22.65},{"id":"n06","text":"Whoever you pick goes to jail.","at":46.1,"t0":23.05,"t1":24.75},{"id":"n07","text":"If you chose number four, you chose the drawing, and so did the police: he's only here because he looks like it.","at":56.12,"t0":28.06,"t1":34.195},{"id":"n08","text":"But the man you saw","at":69.29,"t0":34.645,"t1":35.75},{"id":"n09","text":"is number two.","at":76.2,"t0":38.1,"t1":39.15},{"id":"n10","text":"If you chose number two, you were right, and nobody believed you: he looks nothing like the drawing.","at":79.5,"t0":39.75,"t1":44.91},{"id":"n11","text":"So number four goes to jail for your two guesses, because a pencil cannot draw \"not sure\".","at":93.02,"t0":46.51,"t1":51.74},{"id":"n12","text":"In nineteen eighty-four, a tip told police that Kirk Bloodsworth looked like their sketch.","at":106.28,"t0":53.14,"t1":57.87},{"id":"n13","text":"DNA freed him almost nine years later.","at":116.54,"t0":58.27,"t1":60.455},{"id":"n14","text":"And number two?","at":123.41,"t0":61.705,"t1":62.665},{"id":"n15","text":"He's having chai beside a picture of your guesses.","at":130.31,"t0":65.155,"t1":67.955}];
